def _fork_index(
    results: list[dict | None],
) -> dict[tuple[str, str], set[str]]:
    """Map each forking ``(receiptDigest, upstream)`` edge to audiences.

    Only chains that verified successfully participate, grouped by the
    base receipt digest; delegation paths under different base receipts
    are never compared.  A given ``upstream`` digest pointing at two or
    more distinct next-hop audiences within one base-receipt group is a
    fork; a mere prefix extension -- the same path growing longer --
    adds no audience and is not a fork.
    """
    groups: dict[str, dict[str, set[str]]] = {}
    for result in results:
        if result is None:
            continue
        receipt_digest = result[DELEGATION_RECEIPT_DIGEST]
        edges = groups.setdefault(receipt_digest, {})
        upstream = receipt_digest
        for hop in result[DELEGATION_HOPS]:
            edges.setdefault(upstream, set()).add(hop[DELEGATION_AUDIENCE])
            upstream = hop[DELEGATION_UPSTREAM]
    fork_edges: dict[tuple[str, str], set[str]] = {}
    for receipt_digest, edges in groups.items():
        for upstream, audiences in edges.items():
            if len(audiences) > 1:
                fork_edges[(receipt_digest, upstream)] = audiences
    return fork_edges

