import hashlib, hmac, json

def compact(obj):
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")

SECRET="11"*32
POLICY={"batch":"batch-1","sites":{"a":{1}},"threshold":1}
def sign(p,s): return hmac.new(bytes.fromhex(s),compact(p),hashlib.sha256).hexdigest()

cp={"batch":POLICY["batch"],"sites":{s:sorted(v) for s,v in sorted(POLICY["sites"].items())},"threshold":POLICY["threshold"]}
report={"error":"boom","id":"item-1","result":None,"status":"invalid-proof"}
def receipt(**over):
    payload={"issuer":"coord","keyVersion":1,"moment":100,"policy":hashlib.sha256(compact(cp)).hexdigest(),
             "items":[{"id":"item-1","digest":"aa"*32,"report":report}],"version":1}
    payload.update(over)
    return compact({"payload":payload,"signature":sign(payload,SECRET)})

from offline_coordination.replication import verify_batch_receipt, verify_batch_receipt_chain, InvalidBatchReceiptError, InvalidReceiptDelegationError

# bool masquerading as int -> TypeError
for mut in [dict(keyVersion=True), dict(moment=True), dict(version=True)]:
    try:
        verify_batch_receipt(receipt(**mut), POLICY, {"coord":[{"version":1,"secret":SECRET,"notBefore":0,"notAfter":10**9,"revoked":False}]},200)
        print("NO RAISE", mut)
    except TypeError as e:
        print("TypeError OK:", mut, "->", e)
    except InvalidBatchReceiptError as e:
        print("WRONG (domain error):", mut, "->", e)

# bad value still domain error
try:
    verify_batch_receipt(receipt(version=2), POLICY, {"coord":[{"version":1,"secret":SECRET,"notBefore":0,"notAfter":10**9,"revoked":False}]},200)
except InvalidBatchReceiptError as e:
    print("domain error OK: version=2 ->", type(e).__name__)
except TypeError as e:
    print("WRONG TypeError version=2:", e)
